def transform(grid):
    g = np.array(grid).copy()
    bg = background(g)
    H, W = g.shape
    emit(g, "Start: colour-9 shapes are anchors; objects touching a 9 will be pushed away from it.")
    objs = [o for o in objects(g, bg=bg) if o["colour"] != 9]
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    names = {(-1, 0): "up", (1, 0): "down", (0, -1): "left", (0, 1): "right"}
    for o in objs:
        cells = o["cells"]
        cs = set(cells)
        d = None
        for (y, x) in cells:
            for dy, dx in dirs:
                ny, nx = y - dy, x - dx  # 9 on the opposite side of motion
                if 0 <= ny < H and 0 <= nx < W and g[ny, nx] == 9 and (ny, nx) not in cs:
                    d = (dy, dx)
                    break
            if d:
                break
        if d is None:
            continue
        col = o["colour"]
        for (y, x) in cells:
            g[y, x] = bg
        dy, dx = d
        k = 0
        while True:
            ok = True
            for (y, x) in cells:
                ny, nx = y + (k + 1) * dy, x + (k + 1) * dx
                if not (0 <= ny < H and 0 <= nx < W) or g[ny, nx] != bg:
                    ok = False
                    break
            if not ok:
                break
            k += 1
        for (y, x) in cells:
            g[y + k * dy, x + k * dx] = col
        emit(g, f"Colour-{col} object touches a 9, so it slides {names[d]} to the border ({k} cells).")
    emit(g, "Final: every object touching a 9 has been pushed to the edge.")
    return g
